(224791, 'こっちへ 来てください。', 'こっちへ きてください。', 'Hãy đến phía này.'),
(224792, 'そっちは どうですか。', 'そっちは どうですか。', 'Bên đó thế nào?'),
(224793, '駅は あっちです。', 'えきは あっちです。', 'Nhà ga ở đằng kia.'),
(224794, 'どっちが いい？', 'どっちが いい？', 'Cái nào tốt hơn?'),
(224795, 'みんなで 楽しく 踊ります。', 'みんなで たのしく おどります。', 'Mọi người cùng nhau nhảy múa vui vẻ.'),
(224796, 'この 店は 安いけど、おいしいです。', 'この みせは やすいけど、おいしいです。', 'Quán này rẻ nhưng ngon.'),
(224797, 'お腹がいっぱいです。', 'おなかがいっぱいです。', 'No bụng rồi.'),
(224798, 'よかったら。', 'よかったら。', 'Nếu được thì.'),
(224799, '【N5】デパートで いろいろな 物を 買いました。', 'でぱーとで いろいろな ものを かいました。', 'Tôi đã mua nhiều đồ đa dạng ở trung tâm thương mại.'),
(224800, '明日京都へ行く？', 'あしたきょうとへいく？', 'Ngày mai cậu đi Kyoto không?'),
(224801, 'うん、行く。', 'うん、いく。', 'Ừ, tớ đi.'),
(224802, 'ううん、行かない。', 'ううん、いかない。', 'Không, tớ không đi.'),
(224803, '毎日忙しい？', 'まいにちいそがしい？', 'Cậu bận mỗi ngày à?'),
(224804, 'うん、忙しい。', 'うん、いそがしい。', 'Ừ, bận lắm.'),
(224805, '暇？', 'ひま？', 'Rảnh không?'),
(224806, 'ううん、暇じゃない。', 'ううん、ひまじゃない。', 'Không, tớ không rảnh.'),
(224807, '富士山はどうだった？', 'ふじさんはどうだった？', 'Núi phú sĩ thế nào?'),
(224808, '綺麗だった。', 'きれいだった。', 'Rất đẹp.'),
(224809, '「チケットが あるんだけど、一緒に行かない？」「いいね、ぜひ 行こう！」', '「ちけっとが あるんだけど、いっしょにいかない？」「いいね、ぜひ いこう！」', '"Tôi có vé này, bạn có đi cùng không?" "Hay quá, nhất định đi chứ!'),
(224810, '「明日 映画を 見に行かない？」「いいね！行こう。」', '「あした えいがを みにいかない？」「いいね！いこう。」', '"Ngày mai đi xem phim không?" "Hay đấy! đi thôi.'),
